<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Prescriptions | HMS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
:root{--bg:#091b35;--panel:#122b50;--raised:#1b3964;--line:#2c4770;--gold:#edbd3f;--muted:#bdc8db;--green:#75dda6;--red:#ef9297}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#fff;font:14px 'DM Sans',sans-serif}.wrap{max-width:1400px;margin:auto;padding:25px 27px 45px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}h1,h2{font-family:Manrope,sans-serif}h1{margin:0;font-size:29px}h2{margin:0;font-size:15px}.sub,.note{color:var(--muted)}.sub{margin:6px 0}.back{color:var(--gold);text-decoration:none;border:1px solid var(--line);padding:10px 14px;border-radius:8px}.banner{padding:12px 15px;margin-bottom:15px;border:1px solid var(--gold);border-radius:8px;color:var(--gold);background:#2d2715}.error{border-color:var(--red);color:#ffd8da}.grid{display:grid;grid-template-columns:.7fr 1.3fr;gap:16px}.card{overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.head{padding:15px 16px;border-bottom:1px solid var(--line)}.head i{color:var(--gold);margin-right:8px}.body{padding:16px}form label{display:grid;gap:6px;margin-bottom:11px;color:var(--muted);font-size:12px}input,select,textarea{width:100%;min-height:40px;padding:8px 10px;border:1px solid #466387;border-radius:7px;background:#0c2446;color:#fff;font:inherit}textarea{min-height:70px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:11px}button{min-height:40px;padding:0 13px;border:0;border-radius:7px;background:var(--gold);color:#12284a;font-weight:800;cursor:pointer}.table{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse;font-size:12px}th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{background:var(--raised);color:var(--gold);font-size:11px}td small{display:block;margin-top:3px;color:var(--muted)}.badge{display:inline-flex;padding:4px 8px;border-radius:999px;background:var(--gold);color:#11294c;font-size:10px;font-weight:800}.badge.ready{background:var(--green);color:#123a29}.badge.collected{background:#9bc6f0;color:#102c4d}.inline{display:flex;gap:7px;align-items:center}.inline select,.inline button{min-height:31px;padding:4px 8px;font-size:11px}.detail{white-space:normal;min-width:220px;color:#dce6f4;line-height:1.45}.live{color:var(--green);font-size:11px}.empty{text-align:center;color:var(--muted);padding:20px}@media(max-width:950px){.grid{grid-template-columns:1fr}}@media(max-width:560px){.wrap{padding:17px 12px}.top{align-items:flex-start;flex-direction:column}.row{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><header class="top"><div><h1><i class="fa-solid fa-file-prescription" style="color:var(--gold)"></i> Prescriptions</h1><p class="sub">Create prescriptions with complete medicine instructions and track pharmacy status.</p></div><a class="back" href="{{ url('/pharmacy') }}"><i class="fa-solid fa-arrow-left"></i> Pharmacy</a></header>@if(session('status'))<div class="banner"><i class="fa-solid fa-circle-check"></i> {{ session('status') }}</div>@endif @if($errors->any())<div class="banner error"><i class="fa-solid fa-triangle-exclamation"></i> {{ $errors->first() }}</div>@endif
<section class="grid"><article class="card"><div class="head"><h2><i class="fa-solid fa-pen-to-square"></i>Generate prescription</h2></div><div class="body"><p class="note">The prescription is immediately added to the pharmacy queue.</p><form method="POST" action="{{ route('pharmacy.prescriptions.store') }}">@csrf<label>Patient<select name="patient_id" required><option value="">Select patient</option>@foreach($patients as $patient)<option value="{{ $patient->id }}">{{ $patient->patient_code }} · {{ $patient->name }}</option>@endforeach</select></label><label>Prescribed by doctor<select name="doctor_id" required><option value="">Select doctor</option>@foreach($doctors as $doctor)<option value="{{ $doctor->id }}">{{ $doctor->name }} · {{ $doctor->specialty }}</option>@endforeach</select></label><div class="row"><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option>@foreach($medicines as $medicine)<option value="{{ $medicine->id }}">{{ $medicine->name }} · {{ $medicine->stock }} {{ $medicine->unit }} available</option>@endforeach</select></label><label>Quantity<input type="number" name="quantity" min="1" required></label></div><label>Dosage instructions<input name="dosage" placeholder="1 tablet twice daily after meals"></label><label>Duration<input name="duration" placeholder="5 days"></label><button><i class="fa-solid fa-file-circle-plus"></i> Generate prescription</button></form></div></article>
<article class="card"><div class="head"><h2><i class="fa-solid fa-list-check"></i>Prescription details <span class="live">● Live updates every 15 seconds</span></h2></div><div class="table"><table><thead><tr><th>Prescription</th><th>Patient</th><th>Doctor</th><th>Medicine instructions</th><th>Status</th><th>Manage</th></tr></thead><tbody id="prescriptionsBody">@forelse($prescriptions as $prescription)<tr><td>{{ $prescription->code }}<small>{{ $prescription->created_at->format('d M Y, h:i A') }}</small></td><td>{{ $prescription->patient->name }}<small>{{ $prescription->patient->patient_code }}</small></td><td>{{ $prescription->doctor->name }}<small>{{ $prescription->doctor->specialty }}</small></td><td class="detail">{{ $prescription->items->first()->medicine->name ?? '—' }} × {{ $prescription->items->first()->quantity ?? 0 }}<br>{{ $prescription->items->first()->dosage ?? 'No dosage entered' }} · {{ $prescription->items->first()->duration ?? 'No duration entered' }}</td><td><span class="badge {{ strtolower($prescription->status) }}">{{ $prescription->status }}</span></td><td><form class="inline" method="POST" action="{{ route('prescriptions.status', $prescription) }}">@csrf @method('PATCH')<select name="status"><option @selected($prescription->status === 'Preparing')>Preparing</option><option @selected($prescription->status === 'Ready')>Ready</option><option @selected($prescription->status === 'Collected')>Collected</option></select><button type="submit">Save</button></form></td></tr>@empty<tr><td colspan="6" class="empty">No prescriptions generated yet.</td></tr>@endforelse</tbody></table></div></article></section></main><script>
const body=document.getElementById('prescriptionsBody');function esc(value){const el=document.createElement('span');el.textContent=value ?? '';return el.innerHTML}async function refreshPrescriptions(){try{const response=await fetch('{{ route('prescriptions.live') }}',{headers:{Accept:'application/json'}});if(!response.ok)return;const list=await response.json();body.innerHTML=list.length?list.map(p=>{const i=p.items?.[0];return`<tr><td>${esc(p.code)}<small>${esc(p.created_at)}</small></td><td>${esc(p.patient?.name)}<small>${esc(p.patient?.patient_code)}</small></td><td>${esc(p.doctor?.name)}<small>${esc(p.doctor?.specialty)}</small></td><td class="detail">${esc(i?.medicine?.name||'—')} × ${esc(i?.quantity||0)}<br>${esc(i?.dosage||'No dosage entered')} · ${esc(i?.duration||'No duration entered')}</td><td><span class="badge ${String(p.status).toLowerCase()}">${esc(p.status)}</span></td><td>Refresh page to manage</td></tr>`}).join(''):'<tr><td colspan="6" class="empty">No prescriptions generated yet.</td></tr>'}catch(error){}}setInterval(refreshPrescriptions,15000);
</script></body></html>